Your version doesn't work because C passes arguments **by value**: the function gets copies of `a` and `b`, swaps the copies, and then throws them away. To change the caller's variables, pass their addresses.

```c
#include <stdio.h>

void swap(int *a, int *b)
{
    int tmp = *a;   /* read the value a points to */
    *a = *b;        /* write b's value into a's location */
    *b = tmp;
}

int main(void)
{
    int x = 1, y = 2;
    swap(&x, &y);   /* pass addresses, not values */
    printf("x=%d y=%d\n", x, y);   /* x=2 y=1 */
    return 0;
}
```

Steps:
1. Change the parameters to `int *`. A pointer parameter is a parameter that holds an address.
2. Inside the function, use `*a` and `*b` to read and write the original variables.
3. When you call it, pass `&x` and `&y`.

Key points:
- You can only change a caller's variable if you have its address.
- Don't pass `NULL` to `swap`. It would crash on `*a`.

Why does this segfault?

```c
char *s = "hello";
s[0] = 'H';
```

`"hello"` is a **string literal**: text written directly in your source code. The compiler usually puts string literals in read-only memory. `s` points into that memory, so `s[0] = 'H'` tries to write to a read-only page. The OS stops the program, and that's the segmentation fault.

The C standard says modifying a string literal is **undefined behaviour**. Undefined behaviour means the standard makes no promises: it might crash, or it might seem to work.

Fix: make a writable copy in an array.

```c
#include <stdio.h>

int main(void)
{
    char s[] = "hello";   /* array: its own writable copy */
    s[0] = 'H';
    printf("%s\n", s);    /* Hello */
    return 0;
}
```

Key points:
- `char *s = "..."` points at read-only text. Declare it `const char *s` so the compiler catches writes for you.
- `char s[] = "..."` creates a writable array of 6 bytes (5 letters + `'\0'`).

My function prints the wrong size of the array. Why?

```c
#include <stdio.h>
void show(int arr[]) {
    printf("%zu\n", sizeof(arr) / sizeof(arr[0]));
}
int main(void) {
    int a[10] = {0};
    show(a);
}
```

Inside `show`, `arr` is not an array. It's a pointer. When you pass an array to a function it **decays** into a pointer to its first element, and `int arr[]` in a parameter list really means `int *arr`. So `sizeof(arr)` is the size of a pointer (usually 8), and you get `8 / 4 = 2`, not 10. GCC and Clang warn about this with `-Wall` (`-Wsizeof-array-argument`).

Fix: compute the length where the real array is in scope, and pass it in.

```c
#include <stdio.h>

void show(const int *arr, size_t n)
{
    for (size_t i = 0; i < n; i++)
        printf("%d ", arr[i]);
    printf("(count=%zu)\n", n);
}

int main(void)
{
    int a[10] = {0};
    size_t n = sizeof a / sizeof a[0];   /* works here: a is a real array */
    show(a, n);
    return 0;
}
```

Steps:
1. Calculate `sizeof a / sizeof a[0]` in the function that declared the array.
2. Add a `size_t n` parameter and pass the count.
3. Make the pointer `const` if the function only reads the data.

Key points:
- A function that takes an array can never learn its length on its own. Always pass it.
- This is the standard C pattern (`memcpy`, `qsort` and `fwrite` all take a size).

A C string is an array of `char` that ends with a **null terminator** (`'\0'`, the byte 0). Length means "count characters until `'\0'`". A safe copy must never write past the destination buffer, and must always terminate it.

```c
#include <stdio.h>
#include <stddef.h>

size_t my_strlen(const char *s)
{
    size_t n = 0;
    while (s[n] != '\0')
        n++;
    return n;
}

/* Copies at most dst_size-1 chars and always terminates.
   Returns the length of src, so the caller can detect truncation. */
size_t safe_copy(char *dst, const char *src, size_t dst_size)
{
    size_t i = 0;
    if (dst_size > 0) {
        while (i < dst_size - 1 && src[i] != '\0') {
            dst[i] = src[i];
            i++;
        }
        dst[i] = '\0';
    }
    return my_strlen(src);
}

int main(void)
{
    char buf[6];
    size_t need = safe_copy(buf, "hello world", sizeof buf);
    printf("buf=\"%s\" len=%zu\n", buf, my_strlen(buf));
    if (need >= sizeof buf)
        printf("truncated: needed %zu bytes\n", need + 1);
    return 0;
}
```

Output:
```
buf="hello" len=5
truncated: needed 12 bytes
```

How `safe_copy` works:
1. If the buffer has 0 bytes, it writes nothing.
2. It copies until it runs out of source or reaches `dst_size - 1`, which leaves room for `'\0'`.
3. It always writes the terminator.
4. It returns the source length, so `need >= dst_size` means the text was cut short.

Key points:
- This behaves like BSD `strlcpy`. Plain `strncpy` does *not* always terminate the string.
- `size_t` is the unsigned type for sizes. Use it for lengths and indexes.

Use `malloc`. It asks for memory on the **heap**, a region of memory you request at runtime and give back yourself with `free`.

```c
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    size_t n;
    printf("How many numbers? ");
    if (scanf("%zu", &n) != 1 || n == 0) {
        fprintf(stderr, "invalid count\n");
        return 1;
    }

    int *nums = malloc(n * sizeof *nums);
    if (nums == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }

    long sum = 0;
    for (size_t i = 0; i < n; i++) {
        if (scanf("%d", &nums[i]) != 1) {
            fprintf(stderr, "bad input\n");
            free(nums);
            return 1;
        }
        sum += nums[i];
    }
    printf("sum = %ld\n", sum);

    free(nums);
    return 0;
}
```

Steps:
1. Read the count and check that `scanf` returned 1 (one item read).
2. Allocate `n * sizeof *nums` bytes. `sizeof *nums` stays correct even if you later change the element type.
3. Check for `NULL`. `malloc` returns `NULL` when it fails.
4. Use `nums[i]` exactly like a normal array.
5. Call `free(nums)` on every exit path.

Key points:
- For a very large `n`, `n * sizeof *nums` can overflow. `calloc(n, sizeof *nums)` checks for that overflow for you.
- Variable-length arrays (`int a[n];`) also exist, but they live on the stack and can crash with a large `n`. `malloc` is safer.

Review my code please, it grows an array:

```c
int *grow(int *p, size_t *cap) {
    *cap *= 2;
    p = realloc(p, *cap);
    return p;
}
```

It has three bugs.

1. **The size is in bytes, not elements.** `realloc(p, *cap)` asks for `*cap` bytes. For ints you need `*cap * sizeof *p`.
2. **It leaks on failure.** If `realloc` fails it returns `NULL` but keeps the old block. Writing that `NULL` straight into `p` loses the only pointer to the old block. That's a memory leak.
3. **It updates `*cap` before success.** If the allocation fails, the caller's capacity is already wrong. Also, a starting `cap` of 0 stays 0 forever.

Fixed version (partial snippet: needs `<stdlib.h>` and `<stdint.h>`):

```c
/* Returns 0 on success, -1 on failure (old block untouched). */
int grow(int **p, size_t *cap)
{
    size_t new_cap = (*cap == 0) ? 8 : *cap * 2;
    if (new_cap > SIZE_MAX / sizeof **p)
        return -1;                       /* size would overflow */
    int *tmp = realloc(*p, new_cap * sizeof **p);
    if (tmp == NULL)
        return -1;                       /* *p still valid */
    *p = tmp;
    *cap = new_cap;
    return 0;
}
```

Key points:
- Always `realloc` into a temporary pointer, check it, then assign.
- Taking `int **p` lets the function update the caller's pointer and return a clear status code.

Keep three variables together: the pointer, the count of items used, and the capacity. Grow only when `count == cap`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int grow(int **p, size_t *cap)
{
    size_t new_cap = (*cap == 0) ? 8 : *cap * 2;
    if (new_cap > SIZE_MAX / sizeof **p)
        return -1;
    int *tmp = realloc(*p, new_cap * sizeof **p);
    if (tmp == NULL)
        return -1;
    *p = tmp;
    *cap = new_cap;
    return 0;
}

int main(void)
{
    int *arr = NULL;          /* realloc(NULL, n) acts like malloc */
    size_t count = 0, cap = 0;

    for (int i = 0; i < 20; i++) {
        if (count == cap && grow(&arr, &cap) != 0) {
            free(arr);
            return 1;
        }
        arr[count++] = i * i;
    }
    printf("count=%zu cap=%zu last=%d\n", count, cap, arr[count - 1]);
    free(arr);
    return 0;
}
```

Output: `count=20 cap=32 last=361`.

Key points:
- The capacity doubles (8, 16, 32), so 20 appends need only 3 allocations.

- **By value:** the function gets a full copy of the struct. Changes affect only the copy.
- **By pointer:** the function gets the struct's address. It can read and change the original, and only one address is copied.

```c
#include <stdio.h>

struct point {
    int x;
    int y;
};

void move_copy(struct point p)      { p.x += 10; }       /* changes the copy */
void move_real(struct point *p)     { p->x += 10; }      /* changes the original */
int  sum(const struct point *p)     { return p->x + p->y; } /* read-only access */

int main(void)
{
    struct point a = { 1, 2 };
    move_copy(a);
    printf("after move_copy: x=%d\n", a.x);  /* 1 */
    move_real(&a);
    printf("after move_real: x=%d\n", a.x);  /* 11 */
    printf("sum=%d\n", sum(&a));             /* 13 */
    return 0;
}
```

When to use which:
1. Small struct, read-only (2-3 fields): passing by value is fine and simple.
2. The function must modify the struct: pass by pointer.
3. Large struct, read-only: pass `const struct x *`. This avoids the copy, and the compiler blocks any writes.

Key points:
- `p->x` is shorthand for `(*p).x`.
- Returning a struct by value is also legal, e.g. `struct point make(int x, int y)`.

A **linked list** is a chain of **nodes**. Each node holds a value and a pointer to the next node. The last node's `next` is `NULL`.

```c
#include <stdio.h>
#include <stdlib.h>

struct node {
    int value;
    struct node *next;
};

/* Returns the new head, or NULL if malloc failed (list unchanged). */
struct node *push_front(struct node *head, int value)
{
    struct node *n = malloc(sizeof *n);
    if (n == NULL)
        return NULL;
    n->value = value;
    n->next = head;     /* new node points at the old first node */
    return n;
}

void print_list(const struct node *head)
{
    for (const struct node *cur = head; cur != NULL; cur = cur->next)
        printf("%d -> ", cur->value);
    printf("NULL\n");
}

void free_list(struct node *head)
{
    while (head != NULL) {
        struct node *next = head->next;  /* save before freeing */
        free(head);
        head = next;
    }
}

int main(void)
{
    struct node *head = NULL;
    for (int i = 1; i <= 3; i++) {
        struct node *h = push_front(head, i);
        if (h == NULL) {
            free_list(head);
            return 1;
        }
        head = h;
    }
    print_list(head);   /* 3 -> 2 -> 1 -> NULL */
    free_list(head);
    return 0;
}
```

How it works:
1. `push_front` allocates a node, points it at the current head, and returns it as the new head.
2. `print_list` walks from the head until it reaches `NULL`.
3. `free_list` saves `next` *before* calling `free`. Reading `head->next` after freeing `head` is a use-after-free bug.

Key points:
- Adding at the front is O(1), meaning constant time no matter how long the list is.
- Start with `head = NULL`: an empty list is just a null pointer.

My function returns a string but it prints garbage:

```c
char *greet(void) {
    char msg[32] = "hi there";
    return msg;
}
```

`msg` is a **local variable**. It lives on the stack only while `greet` runs. When the function returns, that memory is released and gets reused by the next function call. You're returning a **dangling pointer**: an address of memory that is no longer yours. Using it is undefined behaviour, and that's why you see garbage. GCC warns: `function returns address of local variable`.

There are three correct fixes:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* 1. Caller provides the buffer (usually best) */
void greet_into(char *buf, size_t size)
{
    snprintf(buf, size, "hi there");
}

/* 2. Return heap memory; caller must free() it */
char *greet_alloc(void)
{
    const char *text = "hi there";
    char *p = malloc(strlen(text) + 1);
    if (p != NULL)
        strcpy(p, text);
    return p;
}

/* 3. Return a pointer to a string literal (read-only, lives forever) */
const char *greet_const(void)
{
    return "hi there";
}

int main(void)
{
    char buf[32];
    greet_into(buf, sizeof buf);
    printf("%s\n", buf);

    char *h = greet_alloc();
    if (h == NULL)
        return 1;
    printf("%s\n", h);
    free(h);

    printf("%s\n", greet_const());
    return 0;
}
```

Key points:
- Never return the address of a non-`static` local variable.
- If a function returns heap memory, document that the caller must `free` it.

A **stack** is last-in, first-out (LIFO): the last item pushed is the first one popped. The functions return an error code instead of writing past the array.

```c
#include <stdio.h>
#include <stdbool.h>

#define STACK_MAX 4

struct stack {
    int items[STACK_MAX];
    size_t top;          /* number of items currently stored */
};

bool push(struct stack *s, int v)
{
    if (s->top == STACK_MAX)
        return false;    /* full: refuse instead of overflowing */
    s->items[s->top++] = v;
    return true;
}

bool pop(struct stack *s, int *out)
{
    if (s->top == 0)
        return false;    /* empty */
    *out = s->items[--s->top];
    return true;
}

int main(void)
{
    struct stack s = { .top = 0 };
    for (int i = 1; i <= 5; i++)
        if (!push(&s, i))
            printf("push %d failed: stack full\n", i);

    int v;
    while (pop(&s, &v))
        printf("popped %d\n", v);   /* 4 3 2 1 */
    return 0;
}
```

How it works:
1. `top` counts the items, so it's also the index of the next free slot.
2. `push` checks for full, writes at `items[top]`, then increments.
3. `pop` checks for empty, decrements, then reads. The value comes back through `out`, and the return value only signals success.

Key points:
- Returning a status separately from the value avoids "magic" error values like -1, which could also be real data.
- For an unlimited stack, use a `malloc`ed array that you grow with `realloc`.

`qsort` sorts any array, so it doesn't know your element type. You give it a **function pointer**: the address of a function it can call to compare two elements. The comparator receives two `const void *` (pointers to "anything") and returns:
- a negative number if a comes first,
- 0 if a and b are equal,
- a positive number if b comes first.

```c
#include <stdio.h>
#include <stdlib.h>

int cmp_int(const void *a, const void *b)
{
    int x = *(const int *)a;   /* convert void* back to int* and read */
    int y = *(const int *)b;
    return (x > y) - (x < y);  /* -1, 0 or 1; avoids overflow from x - y */
}

int main(void)
{
    int a[] = { 42, -7, 19, 0, 3 };
    size_t n = sizeof a / sizeof a[0];

    qsort(a, n, sizeof a[0], cmp_int);   /* pass the function name, no () */

    for (size_t i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");   /* -7 0 3 19 42 */
    return 0;
}
```

Steps:
1. Write a comparator with exactly the signature `int f(const void *, const void *)`.
2. Inside it, cast each pointer to the real element type and read the values.
3. Call `qsort(array, count, element_size, f)`.

Key points:
- Don't use `return x - y;`. It can overflow for large values, and signed overflow is undefined behaviour.

Same pattern. The comparator casts to your struct type and compares the `name` fields with `strcmp`, which already returns negative, 0 or positive.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct person {
    char name[16];
    int age;
};

int cmp_name(const void *a, const void *b)
{
    const struct person *p = a;   /* void* converts implicitly in C */
    const struct person *q = b;
    return strcmp(p->name, q->name);
}

int main(void)
{
    struct person people[] = { {"Zoe", 30}, {"Adam", 25}, {"Mia", 41} };
    size_t n = sizeof people / sizeof people[0];

    qsort(people, n, sizeof people[0], cmp_name);

    for (size_t i = 0; i < n; i++)
        printf("%s %d\n", people[i].name, people[i].age);
    return 0;
}
```

Key points:
- For descending order, swap the arguments: `strcmp(q->name, p->name)`.
- `qsort` is not **stable**: elements that compare equal may come out in any order.

A **header file** (`.h`) holds **declarations**: statements that say a function or type exists. The `.c` files hold the **definitions** (the actual code). Each `.c` file is compiled separately, and the linker joins them.

```c
// mathutil.h
#ifndef MATHUTIL_H
#define MATHUTIL_H

int add(int a, int b);
int clamp(int v, int lo, int hi);

#endif
```

```c
// mathutil.c
#include "mathutil.h"

int add(int a, int b)
{
    return a + b;
}

int clamp(int v, int lo, int hi)
{
    if (v < lo) return lo;
    if (v > hi) return hi;
    return v;
}
```

```c
// main.c
#include <stdio.h>
#include "mathutil.h"

int main(void)
{
    printf("%d\n", add(2, 3));          /* 5 */
    printf("%d\n", clamp(150, 0, 100)); /* 100 */
    return 0;
}
```

Build:
```
cc -std=c11 -Wall -Wextra main.c mathutil.c -o app
```

Steps:
1. Put the function prototypes in `mathutil.h`, wrapped in an **include guard** (`#ifndef/#define/#endif`). The guard stops the header's contents from being included twice in one file.
2. Include the header in `mathutil.c` as well, so the compiler checks that the definitions match the declarations.
3. Include it in every file that calls the functions.
4. Pass all `.c` files to the compiler. Never `#include` a `.c` file.

Key points:
- Use quotes (`"mathutil.h"`) for your own headers and angle brackets (`<stdio.h>`) for system headers.
- Headers should not contain function definitions or variable definitions. Those cause "multiple definition" link errors.

Read the declaration from right to left. `const` applies to whatever is immediately to its left. If nothing is to its left, it applies to whatever is to its right.

1. `const int *p` means "p is a pointer to a const int". You **cannot change the value** through `p`, but you **can** make `p` point somewhere else.
2. `int *const p` means "p is a const pointer to an int". You **can change the value**, but `p` must **always point at the same place**.

```c
#include <stdio.h>

int main(void)
{
    int a = 1, b = 2;

    const int *p = &a;
    /* *p = 5;   error: value is read-only through p */
    p = &b;      /* ok: pointer itself can move */

    int *const q = &a;
    *q = 5;      /* ok: value can change */
    /* q = &b;   error: pointer is fixed */

    printf("a=%d *p=%d *q=%d\n", a, *p, *q);   /* a=5 *p=2 *q=5 */
    return 0;
}
```

Key points:
- `int const *p` means the same as `const int *p`.
- Use `const T *` for function parameters the function only reads, e.g. `size_t strlen(const char *s)`.

Both are locked: you can't change the value through `p`, and you can't point `p` anywhere else.

```c
int a = 1;
const int *const p = &a;
/* *p = 2;   error */
/* p = NULL; error */
```

It must be initialised when declared, because you can never assign it later.

Key points:
- `a` itself is still changeable through its own name (`a = 2;`). `const` only restricts access *through `p`*.
- It's common for fixed lookup tables: `static const char *const names[] = { "a", "b" };`

`volatile` tells the compiler: "this variable can change in ways you can't see, so read it from memory every time and never optimise those reads or writes away."

Without it, the optimiser may keep a value in a CPU register, or skip a read it thinks is redundant.

Valid uses:
1. **Memory-mapped hardware registers** in embedded code, e.g. `volatile uint32_t *status = (uint32_t *)0x40000000;`
2. **A flag set by a signal handler**, e.g. `volatile sig_atomic_t stop = 0;`
3. Local variables that must keep their values across `setjmp`/`longjmp`.

```c
/* partial snippet */
#include <signal.h>
static volatile sig_atomic_t stop = 0;
static void on_sigint(int sig) { (void)sig; stop = 1; }
/* in main: signal(SIGINT, on_sigint); while (!stop) { work(); } */
```

Key points:
- `volatile` is **not** a thread-safety tool. It doesn't make operations atomic and doesn't order memory between threads. Use `<stdatomic.h>` or mutexes for threads.
- Most normal application code never needs it.

A **hash table** stores key/value pairs in an array of **buckets**. A **hash function** turns the key into a number that picks the bucket. Two keys can land in the same bucket (a **collision**). This version handles collisions with **chaining**: each bucket is a linked list.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NBUCKETS 64

struct entry {
    char *key;
    int value;
    struct entry *next;
};

static struct entry *table[NBUCKETS];

static unsigned long hash(const char *s)   /* djb2 */
{
    unsigned long h = 5381;
    for (; *s; s++)
        h = h * 33 + (unsigned char)*s;
    return h % NBUCKETS;
}

int ht_set(const char *key, int value)     /* 0 ok, -1 out of memory */
{
    unsigned long b = hash(key);
    for (struct entry *e = table[b]; e; e = e->next)
        if (strcmp(e->key, key) == 0) { e->value = value; return 0; }

    struct entry *e = malloc(sizeof *e);
    if (!e) return -1;
    e->key = malloc(strlen(key) + 1);
    if (!e->key) { free(e); return -1; }
    strcpy(e->key, key);
    e->value = value;
    e->next = table[b];
    table[b] = e;
    return 0;
}

int *ht_get(const char *key)               /* NULL if missing */
{
    for (struct entry *e = table[hash(key)]; e; e = e->next)
        if (strcmp(e->key, key) == 0) return &e->value;
    return NULL;
}

void ht_free(void)
{
    for (int i = 0; i < NBUCKETS; i++) {
        struct entry *e = table[i];
        while (e) {
            struct entry *next = e->next;
            free(e->key);
            free(e);
            e = next;
        }
        table[i] = NULL;
    }
}

int main(void)
{
    if (ht_set("apple", 3) || ht_set("pear", 5) || ht_set("apple", 7)) {
        ht_free();
        return 1;
    }
    int *v = ht_get("apple");
    printf("apple=%d\n", v ? *v : -1);              /* 7 */
    printf("kiwi %s\n", ht_get("kiwi") ? "found" : "missing");
    ht_free();
    return 0;
}
```

Key points:
- The table copies each key, so the caller's string can change or be freed safely.
- `ht_get` returns a pointer, so "missing" (`NULL`) can't be confused with a stored value.
- This table has a fixed size. A real one resizes when it gets too full.

A **binary search tree (BST)** is a tree where each node has up to two children. Everything in the left subtree is smaller than the node, and everything in the right subtree is larger. That ordering lets search skip half the remaining tree at each step (when the tree is balanced).

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

struct tnode {
    int key;
    struct tnode *left, *right;
};

/* Returns 0 on success, -1 on malloc failure. Duplicates are ignored. */
int insert(struct tnode **root, int key)
{
    while (*root != NULL) {
        if (key == (*root)->key) return 0;
        root = key < (*root)->key ? &(*root)->left : &(*root)->right;
    }
    struct tnode *n = malloc(sizeof *n);
    if (n == NULL) return -1;
    n->key = key;
    n->left = n->right = NULL;
    *root = n;
    return 0;
}

bool contains(const struct tnode *t, int key)
{
    while (t != NULL) {
        if (key == t->key) return true;
        t = key < t->key ? t->left : t->right;
    }
    return false;
}

void print_inorder(const struct tnode *t)   /* left, node, right = sorted */
{
    if (t == NULL) return;
    print_inorder(t->left);
    printf("%d ", t->key);
    print_inorder(t->right);
}

void free_tree(struct tnode *t)             /* children first, then node */
{
    if (t == NULL) return;
    free_tree(t->left);
    free_tree(t->right);
    free(t);
}

int main(void)
{
    struct tnode *root = NULL;
    int keys[] = { 50, 30, 70, 20, 40, 60, 80 };
    for (size_t i = 0; i < sizeof keys / sizeof keys[0]; i++)
        if (insert(&root, keys[i]) != 0) { free_tree(root); return 1; }

    print_inorder(root);
    printf("\ncontains 40: %d, contains 45: %d\n", contains(root, 40), contains(root, 45));
    free_tree(root);
    return 0;
}
```

Key points:
- `insert` takes `struct tnode **` so it can write the new node into the parent's `left`/`right` pointer, or into `root` itself.
- Inserting already-sorted data creates a "tree" that is really a linked list, so search becomes O(n). Balanced trees (AVL, red-black) fix this.

This works on my machine but my friend says it's wrong. Is it?

```c
